#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_new_game_successful_creation(void) {
    // The function new_game() reads from a fixed file "games/words.txt".
    // To test the successful path (file opens, contains words, selects a random word),
    // we must ensure the file exists and has at least one word.
    // The test will call the function and verify the returned struct is correctly initialized.

    // Ensure file exists before calling new_game()
    FILE *fptr = fopen("games/words.txt", "r");
    if (fptr == NULL) {
        // Create directory if it doesn't exist
        system("mkdir -p games");
        // Create dummy file for testing
        fptr = fopen("games/words.txt", "w");
        fprintf(fptr, "testword
");
        fclose(fptr);
    } else {
        fclose(fptr);
    }
    struct game_instance game = new_game();

    // Assert the returned game instance is valid
    TEST_ASSERT_NOT_NULL(game.current_word);
    TEST_ASSERT_TRUE(game.size > 0);
    TEST_ASSERT_TRUE(game.size <= 29); // current_word max length is 30, but hidden array size is 30, and hidden[size]='\0'
    TEST_ASSERT_EQUAL_INT(0, game.incorrect);
    TEST_ASSERT_EQUAL_INT(0, game.guesses_size);

    // Verify hidden word is all underscores of length game.size
    for (int i = 0; i < game.size; i++) {
        TEST_ASSERT_EQUAL('_', game.hidden[i]);
    }
    TEST_ASSERT_EQUAL('\0', game.hidden[game.size]);

    // Verify current_word is not empty and matches size
    TEST_ASSERT_EQUAL_INT(game.size, (int)strlen(game.current_word));

    // Verify guesses array is zeroed (as per memset)
    for (int i = 0; i < 26; i++) {
        TEST_ASSERT_EQUAL(0, game.guesses[i]);
    }
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_new_game_successful_creation);
    return UNITY_END();
}

